{
  "typography": {
    "caption": {
      "fontSize": {
        "pointer": 11,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 16
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontSize": {
        "pointer": 12,
        "touch": 13
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontSize": {
        "pointer": 13,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontSize": {
        "pointer": 14,
        "touch": 15
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 500,
      "letterSpacing": 0
    },
    "title": {
      "fontSize": {
        "pointer": 16,
        "touch": 16
      },
      "lineHeight": {
        "pointer": 24,
        "touch": 24
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontSize": {
        "pointer": 20,
        "touch": 22
      },
      "lineHeight": {
        "pointer": 28,
        "touch": 28
      },
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 26,
        "touch": 28
      },
      "lineHeight": {
        "pointer": 32,
        "touch": 36
      },
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "container": "{radius-container}",
      "modal": "{radius-modal}"
    },
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 44
      },
      "density": {
        "pointer": {
          "pad": 12,
          "gap": 12,
          "surface": 10
        },
        "touch": {
          "pad": 12,
          "gap": 12,
          "surface": 16
        }
      },
      "control": {
        "pointer": {
          "padding": 8,
          "gap": 8,
          "dot": 6,
          "switch": "small"
        },
        "touch": {
          "padding": 8,
          "gap": 8,
          "dot": 8,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 28,
          "lg": 32
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "halo",
      "width": 3,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "shape": {
    "curve": "continuous",
    "corners": {
      "button": "radius"
    }
  },
  "state": {
    "press-scale": 0.97,
    "overlay": {
      "hover": 0,
      "focus": 0,
      "pressed": 0,
      "dragged": 0
    },
    "ripple": false,
    "pressed-opacity": 0.7,
    "accent-pressed-opacity": 0.88,
    "rest-opacity": 0.5,
    "disabled": {
      "content": 0.5,
      "fill": false
    }
  },
  "transition": {
    "enter": {
      "duration": 420,
      "timingFunction": "out-cubic"
    }
  },
  "motion": {
    "fast": {
      "stiffness": 1218,
      "damping": 70
    },
    "default": {
      "stiffness": 520,
      "damping": 34
    },
    "slow": {
      "stiffness": 320,
      "damping": 30
    }
  },
  "controls": "base",
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      },
      "inset": {
        "foreground": "{foreground}",
        "material": null
      },
      "raised": {
        "background": "{raised}",
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": null
      },
      "overlay": {
        "background": "{popover}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "backdropFilter": "none",
        "material": null
      },
      "modal": {
        "background": "{card}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      },
      "inverse": {
        "background": "{inverse}",
        "foreground": "{muted-foreground}",
        "border-color": "{border}",
        "backdropFilter": "none",
        "material": null
      },
      "glass": {
        "foreground": "{foreground}",
        "border-color": "{border}",
        "backdropFilter": "blur(20px)",
        "material": null
      },
      "accent": {
        "background": "{primary}",
        "foreground": "{primary-foreground}",
        "border-color": "{brand-edge}",
        "border-top-color": "{brand-edge}",
        "border-bottom-color": "{brand-edge}",
        "material": null
      },
      "knob": {
        "foreground": "{foreground}",
        "material": null
      },
      "hover": {
        "foreground": "{foreground}",
        "material": null
      },
      "pressed": {
        "foreground": "{foreground}",
        "material": null
      },
      "disabled": {
        "background": "{raised}",
        "foreground": "{foreground}",
        "border-color": "{border}",
        "material": null
      }
    },
    "light": {
      "card": {
        "shadow": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04)"
      },
      "inset": {
        "shadow": "inset 0 1px 1px oklch(0.1686 0.02256 263.693 / 0.06)"
      },
      "raised": {
        "shadow": "inset 0 1px 0 oklch(1 0 0), inset 0 2px 0 oklch(1 0 0 / 0.6), 0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)",
        "border-color": "{border}",
        "border-top-color": "{border}",
        "border-bottom-color": "{border}"
      },
      "overlay": {
        "shadow": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04), 0 12px 28px -10px oklch(0.1686 0.02256 263.693 / 0.22)"
      },
      "modal": {
        "shadow": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04), 0 12px 28px -10px oklch(0.1686 0.02256 263.693 / 0.22)"
      },
      "inverse": {
        "shadow": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04), 0 12px 28px -10px oklch(0.1686 0.02256 263.693 / 0.22)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.8)",
        "shadow": "inset 0 1px 0 oklch(1 0 0), inset 0 2px 0 oklch(1 0 0 / 0.6), 0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)"
      },
      "accent": {
        "shadow": "inset 0 1px 0 oklch(1 0 0 / 0.55), inset 0 -1px 0 oklch(0.42761 0.11265 128.534 / 0.12), 0 1px 0 oklch(0.42761 0.11265 128.534 / 0.14)"
      },
      "knob": {
        "background": "oklch(1 0 0)",
        "gradient": "linear-gradient(180deg, oklch(1 0 0) 0%, {raised} 100%)",
        "shadow": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)",
        "border-color": "{input}"
      },
      "hover": {
        "background": "{popover}",
        "shadow": "inset 0 1px 0 oklch(1 0 0), inset 0 2px 0 oklch(1 0 0 / 0.6), 0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)",
        "border-color": "{border}",
        "border-top-color": "{border}",
        "border-bottom-color": "{border}"
      },
      "pressed": {
        "background": "{muted}",
        "shadow": "inset 0 1px 1px oklch(0.1686 0.02256 263.693 / 0.06)",
        "border-color": "{input}",
        "border-top-color": "{input}",
        "border-bottom-color": "{input}"
      },
      "disabled": {
        "shadow": "inset 0 1px 0 oklch(1 0 0), inset 0 2px 0 oklch(1 0 0 / 0.6), 0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)"
      }
    },
    "dark": {
      "card": {
        "shadow": "0 1px 0 oklch(0 0 0 / 0.35)"
      },
      "inset": {
        "shadow": "inset 0 1px 1px oklch(0 0 0 / 0.2)"
      },
      "raised": {
        "shadow": "inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 1px 1px oklch(1 0 0 / 0.08), 0 1px 1px oklch(0 0 0 / 0.12)",
        "border-color": "oklch(0 0 0 / 0.5)",
        "border-top-color": "oklch(0 0 0 / 0.5)",
        "border-bottom-color": "oklch(0 0 0 / 0.5)"
      },
      "overlay": {
        "shadow": "0 1px 0 oklch(0 0 0 / 0.4), 0 16px 32px -10px oklch(0 0 0 / 0.6)"
      },
      "modal": {
        "shadow": "0 1px 0 oklch(0 0 0 / 0.4), 0 16px 32px -10px oklch(0 0 0 / 0.6)"
      },
      "inverse": {
        "shadow": "0 1px 0 oklch(0 0 0 / 0.4), 0 16px 32px -10px oklch(0 0 0 / 0.6)"
      },
      "glass": {
        "background": "oklch(from {card} l c h / 0.78)",
        "shadow": "inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 1px 1px oklch(1 0 0 / 0.08), 0 1px 1px oklch(0 0 0 / 0.12)"
      },
      "accent": {
        "shadow": "inset 0 0 0 1px oklch(1 0 0 / 0.22), inset 0 1px 1px oklch(1 0 0 / 0.35), 0 1px 1px oklch(0 0 0 / 0.12)"
      },
      "knob": {
        "background": "{knob}",
        "gradient": "linear-gradient(180deg, {foreground} 0%, oklch(0.88185 0.00589 264.53) 100%)",
        "shadow": "0 1px 1px oklch(0 0 0 / 0.12)",
        "border-color": "oklch(0.8324 0.00597 264.528)"
      },
      "hover": {
        "background": "{input}",
        "shadow": "inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 1px 1px oklch(1 0 0 / 0.08), 0 1px 1px oklch(0 0 0 / 0.12)",
        "border-color": "oklch(0 0 0 / 0.5)",
        "border-top-color": "oklch(0 0 0 / 0.5)",
        "border-bottom-color": "oklch(0 0 0 / 0.5)"
      },
      "pressed": {
        "background": "{line}",
        "shadow": "inset 0 1px 1px oklch(0 0 0 / 0.2)",
        "border-color": "oklch(0 0 0 / 0.5)",
        "border-top-color": "oklch(0 0 0 / 0.5)",
        "border-bottom-color": "oklch(0 0 0 / 0.5)"
      },
      "disabled": {
        "shadow": "inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 1px 1px oklch(1 0 0 / 0.08), 0 1px 1px oklch(0 0 0 / 0.12)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.05)",
      "md": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04)",
      "lg": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04), 0 12px 28px -10px oklch(0.1686 0.02256 263.693 / 0.22)",
      "xl": "0 1px 0 oklch(0.1686 0.02256 263.693 / 0.04), 0 12px 28px -10px oklch(0.1686 0.02256 263.693 / 0.22)",
      "inset": "inset 0 1px 1px oklch(0.1686 0.02256 263.693 / 0.06)",
      "edge": {
        "surface": "inset 0 1px 0 oklch(1 0 0), inset 0 2px 0 oklch(1 0 0 / 0.6)",
        "accent": "inset 0 1px 0 oklch(1 0 0 / 0.55), inset 0 -1px 0 oklch(0.42761 0.11265 128.534 / 0.12), 0 1px 0 oklch(0.42761 0.11265 128.534 / 0.14)"
      }
    },
    "dark": {
      "sm": "0 1px 1px oklch(0 0 0 / 0.12)",
      "md": "0 1px 0 oklch(0 0 0 / 0.35)",
      "lg": "0 1px 0 oklch(0 0 0 / 0.4), 0 16px 32px -10px oklch(0 0 0 / 0.6)",
      "xl": "0 1px 0 oklch(0 0 0 / 0.4), 0 16px 32px -10px oklch(0 0 0 / 0.6)",
      "inset": "inset 0 1px 1px oklch(0 0 0 / 0.2)",
      "edge": {
        "surface": "inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 1px 1px oklch(1 0 0 / 0.08)",
        "accent": "inset 0 0 0 1px oklch(1 0 0 / 0.22), inset 0 1px 1px oklch(1 0 0 / 0.35), 0 1px 1px oklch(0 0 0 / 0.12)"
      }
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "NSH Gallery UI (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "NSH Gallery UI default theme: graphite dark and paper light surfaces with citrus lime (`#c6ef6a`) brand fill, continuous squircle corners, spring motion physics, and layered surface finishes.",
        "elevation": "Tactile layered elevation: inner top-edge highlights (`inset`), 1px hairline borders, contact + cast drop shadows (`card`, `menu`, `modal`, `inverse`), and translucent frosted glass (`glass` with 80% popover alpha).",
        "dos": [
          "Preserve the citrus accent (`primary` / `primary-foreground`) for primary actions, active runs, and focus highlights.",
          "Use `inset` wells inside cards and `raised` surfaces for controls sitting on cards, paired with continuous squircle corners (`shape.curve: \"continuous\"`).",
          "Apply tactile spring press feedback (`state.press-scale: 0.97`, `motion.default` / `motion.slow`)."
        ],
        "donts": [
          "Do not flatten shadows or remove inner highlights on `card`, `raised`, `inset`, or `pill` finishes.",
          "Do not merge distinct semantic finishes (`light` vs `accent`, `thumb` vs `raised`, `knob` vs `handle`)."
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Semantic typography roles referencing tier-specific font.size and font.line-height.",
    "caption": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.caption}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.label}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.title}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.headline}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.display}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles by layer, referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for in-page elements: buttons, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": "{dimension.radius.container}",
        "$description": "Corner radius for containers and overlays: cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": "{dimension.radius.modal}",
        "$description": "Corner radius for modal surfaces: dialogs, sheets, and drawers."
      }
    },
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "halo"
        }
      },
      "$description": "Focus ring geometry and style enum.",
      "width": {
        "$value": {
          "value": 3,
          "unit": "px"
        },
        "$description": "Focus ring stroke width."
      },
      "offset": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Focus ring outward offset from control bounds."
      }
    },
    "radius": {
      "$type": "dimension",
      "$description": "Corner radius roles by layer (8px control, 12px container, 14px modal) referenced by semantic shape roles.",
      "control": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for in-page controls, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": {
          "value": 12,
          "unit": "px"
        },
        "$description": "Corner radius for cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": {
          "value": 14,
          "unit": "px"
        },
        "$description": "Corner radius for dialogs, sheets, and drawers."
      }
    },
    "size": {
      "$description": "Ergonomic sizing scales for pointer input.",
      "hit": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Minimum hit target size (0 disables padding expansion)."
      },
      "density": {
        "$description": "Page-level padding, gap, and surface spacing metrics.",
        "pad": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        },
        "surface": {
          "$value": {
            "value": 10,
            "unit": "px"
          }
        }
      },
